import * as React from "react";
import styles from "./ScorecardQuestionsView.module.scss";
// Interface ungaludaiya original file-il irunthu
import { QuestionItem } from "../../SelectionProcess/services/QuestionnaireApi/IQuestionnaireApi";

interface ScorecardQuestionsViewProps {
  questionnaire: QuestionItem[];
  onClose: () => void;
}

const ScorecardQuestionsView: React.FC<ScorecardQuestionsViewProps> = ({ questionnaire, onClose }) => {
  return (
    <div className={styles.qaContainer}>
      <div className={styles.qaHeader}>
        <h3>Questions and Answers</h3>
      </div>

      <div className={styles.qaBody}>
        {questionnaire && questionnaire.length > 0 ? (
          questionnaire.map((q, index) => (
            <div key={q.id || index} className={styles.questionCard}>
              <div className={styles.questionTitle}>
                <span className={styles.qNumber}>Q{index + 1}</span>
                <p
                  dangerouslySetInnerHTML={{
                    __html: q.question
                      ?.replace(/<p>/gi, "")
                      .replace(/<\/p>/gi, "")
                      .replace(/<br\s*\/?>/gi, "")
                      .trim(),
                  }}
                />
              </div>
              <div className={styles.answerBox}>
                <strong>Expected Answer:</strong>
                <p dangerouslySetInnerHTML={{ __html: q.answer || "No answer provided" }} />
              </div>
            </div>
          ))
        ) : (
          <div className={styles.noData}>
            <p>No Questions and Answers found for this candidate.</p>
          </div>
        )}
      </div>

      <div className={styles.qaFooter}>
        <button className={styles.closeBtn} onClick={onClose}>
          Close View
        </button>
      </div>
    </div>
  );
};

export default ScorecardQuestionsView;